    var toGroup = [];
    (p.changedFunctions || []).forEach(function (cf) {
      if (cf.status === 'added') added[cf.name] = cf;
      if (cf.status === 'changed' && cf.kind === 'Group' && cf.kindBefore && cf.kindBefore !== 'Group') {
        toGroup.push(cf.name);
